#!/usr/bin/env bash
# Step 5 – writes deploy/helm/intimed/values-gcp-<env>.generated.yaml from `terraform output` (no secrets in it).
source "$(dirname "$0")/common.sh"
need terraform jq
OUT="$ROOT/deploy/helm/intimed/values-gcp-$ENV.generated.yaml"
J=$(terraform -chdir="$TF_DIR" output -json)
v() { echo "$J" | jq -r ".$1.value"; }
CA=$(v sql_server_ca_pem | sed 's/^/    /')
cat > "$OUT" <<YAML
# generated by deploy/gcp/scripts/render-values.sh – $(date -u +%FT%TZ)
cloud: gcp
image:
  repository: $(v artifact_registry)/intimed/platform
  tag: "${IMAGE_TAG:-2.2.0}"
  digest: "${IMAGE_DIGEST:-}"
gcp:
  projectId: $(v project_id)
  region: $(v region)
  gsaEmail: $(v app_gsa_email)
  evidenceBucket: $(v evidence_bucket)
  auditBucket: $(v audit_bucket)
  sqlServerCaPem: |
$CA
  console:
    hostname: "${CONSOLE_HOSTNAME:?set CONSOLE_HOSTNAME (public DNS name of the console)}"
    ipName: $(v console_ip_name)
    armorPolicy: $(v armor_policy)
database:
  host: $(v sql_private_ip)
devices:
  loadBalancerIP: $(v devices_lb_ip)
  dnsName: "${DEVICES_DNS_NAME:-}"
networkPolicy:
  appGatewaySubnetCidr: $(v subnet_cidrs | jq -r .proxy_only)
  postgresSubnetCidr: $(v subnet_cidrs | jq -r .psa)
  deviceSourceCidrs: $(v device_source_cidrs | jq -c .)
YAML
echo "wrote $OUT"
